다음 C 프로그램의 출력 결과는?

#include <stdio.h>

int repeat(int a, int b) {
    if (b == 0)
        return a;
    else if (b % 2 == 0)
        return repeat(a + a, b / 2);
    else
        return repeat(a + a, b / 2) + a;
}

int main() {
    printf("%d", repeat(3, 6));
    return 0;
}

